	for rows.Next() {
		var report domain.ImportReport
		var encoded []byte
		if err = rows.Scan(&report.ID, &report.CreatedAt, &report.Machine.ID, &report.Machine.Hostname, &report.Machine.OS, &report.Machine.Arch, &encoded); err != nil {
