import json,pathlib,collections

def shape(x,depth=3):
 if depth<0: return type(x).__name__
 if isinstance(x,dict): return {k:shape(v,depth-1) for k,v in x.items()}
 if isinstance(x,list): return {'count':len(x),'items':[shape(v,depth-1) for v in x[:2]]}
 if isinstance(x,str): return f'string({len(x)})'
 return type(x).__name__
for p in pathlib.Path('/tmp/traicr-amp-inspection').glob('*.json'):
 d=json.loads(p.read_text()); ms=d['messages']; bs=[b for m in ms for b in m['content']]
 print('\nFILE',p.name)
 print('env',shape(d.get('env'),3));print('meta',shape(d.get('meta'),4));print('skills',shape(d.get('activatedSkills'),3))
 print('states',collections.Counter(str(m.get('state')) for m in ms if m.get('state')))
 print('hidden',[(m['role'],b.get('type'),len(b.get('text',''))) for m in ms for b in m['content'] if b.get('hidden')])
 for t in ['summary','image']:
  b=next((b for b in bs if b.get('type')==t),None);print(t,shape(b,5))
 print('tool_run_error',shape(next((b['run'] for b in bs if b.get('type')=='tool_result' and b['run']['status']=='error'),None),4))
 print('run_progress',shape(next((b['run'].get('progress') for b in bs if b.get('type')=='tool_result' and b['run'].get('progress')),None),5))
 calls={b['id']:b['name'] for b in bs if b.get('type')=='tool_use'}
 for name in ['skill','oracle','Task','finder','read_web_page','apply_patch','create_thread','view_media']:
  b=next((b for b in bs if b.get('type')=='tool_result' and calls.get(b['toolUseID'])==name),None)
  if b: print('result',name,shape(b['run'],4))
 print('usage example',next((m['usage'] for m in ms if m.get('usage')),None))
