func TestAmpExportInspection(t *testing.T) {
	for _, name := range []string{"automation", "review", "homelab", "current"} {
		data, err := os.ReadFile("/tmp/traicr-amp-inspection/" + name + ".json")
		if err != nil {
			t.Fatal(err)
		}
		result, err := Run(context.Background(), domain.Descriptor{Harness: "amp"}, fstest.MapFS{"source/export.json": {Data: data}})
		if err != nil {
			t.Fatal(err)
		}
		blankResults, results, missingTimes, emptyAttachments := 0, 0, 0, 0
		for _, event := range result.Events {
			if event.Kind == "tool_result" {
				results++
				if event.Text == "" {
					blankResults++
				}
			}
			if event.Timestamp == "" {
				missingTimes++
			}
			for _, a := range event.Attachments {
				if a.Name == "" && a.MediaType == "" && a.Path == "" && a.URL == "" {
					emptyAttachments++
				}
			}
		}
		t.Logf("%s: events=%d warnings=%d toolResults=%d blankResults=%d missingEventTimes=%d emptyAttachments=%d", name, len(result.Events), len(result.Warnings), results, blankResults, missingTimes, emptyAttachments)
	}
}

func TestAmpNumericIdentityInspection(t *testing.T) {
	message := map[string]any{"messageId": 7, "role": "assistant", "readAt": "2026-01-01T00:00:00Z", "content": []any{map[string]any{"type": "text", "text": "unchanged text"}}}
	var keys []string
	for _, readAt := range []string{"2026-01-01T00:00:00Z", "2026-01-02T00:00:00Z"} {
		message["readAt"] = readAt
