		result, err := Run(context.Background(), domain.Descriptor{Harness: "amp"}, fstest.MapFS{"source/export.json": {Data: data}})
		if err != nil || len(result.Events) != 1 {
			t.Fatalf("normalization: %v", err)
		}
		keys = append(keys, result.Events[0].Key)
	}
	t.Logf("same numeric messageId and text, changed readAt: event identity changed=%t", keys[0] != keys[1])
}
