	if err != nil {
		return err
	}
	result, err := tx.ExecContext(ctx, "INSERT INTO imports(created_at,machine_id) VALUES(?,?)", report.CreatedAt, m.ID)
	if err != nil {
		return err
	}
	report.ID, err = result.LastInsertId()
	if err != nil {
		return err
	}
	return tx.Commit()
}

