func (s *Store) DeleteTrace(ctx context.Context, id int64) error {
	select {
	case s.writer <- struct{}{}:
		defer func() { <-s.writer }()
	case <-ctx.Done():
		return ctx.Err()
	}
	result, err := s.db.ExecContext(ctx, "DELETE FROM traces WHERE id=?", id)
	if err != nil {
		return err
	}
	deleted, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if deleted == 0 {
		return sql.ErrNoRows
	}
	return s.gc(ctx)
}

func (s *Store) GC(ctx context.Context) error {
	select {
	case s.writer <- struct{}{}:
		defer func() { <-s.writer }()
	case <-ctx.Done():
		return ctx.Err()
	}
	return s.gc(ctx)
}

func (s *Store) gc(ctx context.Context) error {
	type unused struct{ digest, path string }
	for {
		rows, err := s.db.QueryContext(ctx, "SELECT digest,path FROM source_objects WHERE NOT EXISTS(SELECT 1 FROM revision_objects WHERE object_digest=source_objects.digest) LIMIT 100")
		if err != nil {
			return err
		}
		var objects []unused
		for rows.Next() {
			var object unused
			if err = rows.Scan(&object.digest, &object.path); err != nil {
				rows.Close()
				return err
			}
			objects = append(objects, object)
		}
		if err = errors.Join(rows.Err(), rows.Close()); err != nil {
			return err
		}
		for _, object := range objects {
			if err = os.Remove(filepath.Join(s.objects, object.path)); err != nil && !errors.Is(err, os.ErrNotExist) {
				return err
			}
			if _, err = s.db.ExecContext(ctx, "DELETE FROM source_objects WHERE digest=? AND NOT EXISTS(SELECT 1 FROM revision_objects WHERE object_digest=?)", object.digest, object.digest); err != nil {
				return err
			}
		}
		if len(objects) < 100 {
			break
		}
	}
	return filepath.WalkDir(s.objects, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			return nil
		}
		relative, err := filepath.Rel(s.objects, path)
		if err != nil {
			return err
		}
		var referenced bool
		if err := s.db.QueryRowContext(ctx, "SELECT EXISTS(SELECT 1 FROM source_objects WHERE path=?)", relative).Scan(&referenced); err != nil {
			return err
		}
		if !referenced {
			return os.Remove(path)
		}
		return nil
	})
}

// Adapt Traicr's merged, normalized records to Pi's HTML session-entry contract.
// Native source files remain authoritative and are available through the details page.

function nativeMessageKey(event) {
  if (event.metadata?.transcript_message) return event.metadata.transcript_message;
  const key = event.key || String(event.id);
  const native = key.slice(key.indexOf(":") + 1);
  if (native.startsWith("sha256:")) return key;
  return native.replace(/:\d+$/, "");
}

function blockIndex(event) {
  if (Number.isInteger(event.metadata?.transcript_block)) return event.metadata.transcript_block;
  const match = event.key?.match(/:(\d+)$/);
  return match ? Number(match[1]) : event.id;
}

