+  const duration = starts.length && ends.length ? Math.max(...ends) - Math.min(...starts) : undefined;
+  return details('Message details & source', fields({Model:message?.model,Provider:message?.provider,Timestamp:entry.timestamp,'Generation span':duration === undefined ? undefined : `${duration} ms`,State:native.state,Usage:native.usage},escape) + `<ul>${links}</ul>`, escape);
