	value := app.setSession(w, "login")
	r.AddCookie(&http.Cookie{Name: sessionCookie, Value: value})
	// Replace a stale cookie rather than allowing it to select the form token.
	r.Header.Set("Cookie", sessionCookie+"="+value)
