package adapters

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/regutierrez/traicr/internal/archive"
	"github.com/regutierrez/traicr/internal/domain"
)

const (
	commandTimeout = 30 * time.Second
	listLimit      = 500
	maxListBytes   = 32 << 20
	maxExportBytes = 512 << 20
)

type commandAdapter struct {
	name       string
	format     string
	executable string
}

type commandTrace struct {
	ID         string
	Title      string
	UpdatedAt  string
	ParentID   string
	CWD        string
	Repository domain.Repository
}

func (a commandAdapter) Name() string { return a.name }

func (a commandAdapter) Discover(ctx context.Context, _ []string) Source {
	traces, warnings := a.list(ctx)
	return Source{Harness: a.name, Location: a.executable + " CLI", Traces: len(traces), Warnings: warnings}
}

func (a commandAdapter) Collect(ctx context.Context, _ []string, progress Progress) (Result, error) {
	traces, warnings := a.list(ctx)
	base, err := os.MkdirTemp("", "traicr-"+a.name+"-*")
	if err != nil {
		return Result{}, err
	}
	result := Result{Warnings: warnings, Cleanup: func() { os.RemoveAll(base) }}
	for index, trace := range traces {
		progress.report(index+1, len(traces))
		dir := filepath.Join(base, fmt.Sprintf("%06d", index+1))
		if err := os.MkdirAll(filepath.Join(dir, "source"), 0o700); err != nil {
			result.Cleanup()
			return Result{}, err
		}
		path := filepath.Join(dir, "source", "export.json")
		args := []string{"export", trace.ID}
		if a.name == "amp" {
			args = []string{"threads", "export", trace.ID}
		}
		limit := int64(maxExportBytes)
		if a.name == "amp" {
			limit = domain.MaxAmpExportBytes
		}
		if err := runToFile(ctx, a.executable, args, path, limit); err != nil {
			result.Warnings = append(result.Warnings, warning("export_failed", fmt.Sprintf("%s %s: %v", a.name, trace.ID, err)))
			os.RemoveAll(dir)
			continue
		}
		exported, inspectErr := inspectCommandExport(a.name, path, trace.ID)
		if inspectErr != nil {
			result.Warnings = append(result.Warnings, warning("unknown_schema", fmt.Sprintf("%s %s export has an unsupported schema; bytes were preserved: %v", a.name, trace.ID, inspectErr)))
		} else {
			if exported.Title != "" {
				trace.Title = exported.Title
			}
			if exported.UpdatedAt != "" {
				// Amp's list index lags the thread's own updatedAt by hours, so a mismatch
				// there reflects server indexing, not an edit during collection.
				if a.name != "amp" && trace.UpdatedAt != "" && trace.UpdatedAt != exported.UpdatedAt {
					result.Warnings = append(result.Warnings, warning("live_source_changed", fmt.Sprintf("%s %s changed between listing and export", a.name, trace.ID)))
				}
				trace.UpdatedAt = exported.UpdatedAt
			}
			trace.ParentID = exported.ParentID
			trace.CWD = exported.CWD
			trace.Repository = exported.Repository
		}
		descriptor := domain.Descriptor{
			Harness:             a.name,
			Adapter:             a.format,
			NativeTraceID:       trace.ID,
			NativeUpdatedAt:     trace.UpdatedAt,
			ParentNativeTraceID: trace.ParentID,
			Title:               trace.Title,
			WorkingDirectory:    trace.CWD,
		}
		if trace.Repository != (domain.Repository{}) {
			descriptor.Repository = trace.Repository
		} else if trace.CWD != "" {
			root, remote := gitRepository(trace.CWD)
			descriptor.Repository = domain.Repository{Root: root, Remote: remote}
		}
		result.Inputs = append(result.Inputs, archive.Input{Descriptor: descriptor, Directory: dir})
	}
	return result, nil
}

func (a commandAdapter) list(ctx context.Context) ([]commandTrace, []domain.Warning) {
	if _, err := exec.LookPath(a.executable); err != nil {
		return nil, []domain.Warning{warning("missing_executable", a.executable+" is not installed or not on PATH")}
	}
	if a.name == "amp" {
		return a.listAmp(ctx)
	}
	data, err := runOutput(ctx, a.executable, []string{"session", "list", "--format", "json"}, maxListBytes)
	if err != nil {
		return nil, []domain.Warning{warning("command_failed", "opencode session list failed: "+err.Error())}
	}
	traces, err := parseOpenCodeList(data)
	if err != nil {
		return nil, []domain.Warning{warning("unknown_schema", "opencode session list returned an unsupported schema: "+err.Error())}
	}
	return traces, nil
}

// Amp orders offset pages inconsistently, so later pages can repeat earlier
// threads and skip others. Repeats are dropped here; skipped threads are picked
// up by a later collection once the listing settles.
func (a commandAdapter) listAmp(ctx context.Context) ([]commandTrace, []domain.Warning) {
	var traces []commandTrace
	seen := map[string]bool{}
	repeated := 0
	for offset := 0; ; offset += listLimit {
		args := []string{"threads", "list", "--json", "--include-archived", "--limit", strconv.Itoa(listLimit), "--offset", strconv.Itoa(offset)}
		data, err := runOutput(ctx, a.executable, args, maxListBytes)
		if err != nil {
			return traces, []domain.Warning{warning("command_failed", "amp threads list failed; check authentication and network access: "+err.Error())}
		}
		page, err := parseAmpList(data)
		if err != nil {
			return traces, []domain.Warning{warning("unknown_schema", "amp threads list returned an unsupported schema: "+err.Error())}
		}
		for _, trace := range page {
			if seen[trace.ID] {
				repeated++
				continue
			}
			seen[trace.ID] = true
			traces = append(traces, trace)
		}
		if len(page) < listLimit {
			if repeated > 0 {
				return traces, []domain.Warning{warning("unstable_listing", fmt.Sprintf("amp threads list pages overlapped; %d repeated entries were dropped and some threads may be missing until the next collection", repeated))}
			}
			return traces, nil
		}
	}
}

func parseAmpList(data []byte) ([]commandTrace, error) {
	var entries []struct {
		ID           string `json:"id"`
		Title        string `json:"title"`
		Updated      string `json:"updated"`
		Tree         string `json:"tree"`
		MessageCount int    `json:"messageCount"`
	}
	if err := json.Unmarshal(data, &entries); err != nil {
		return nil, err
	}
	traces := make([]commandTrace, len(entries))
	for index, entry := range entries {
		if entry.ID == "" || entry.Updated == "" {
			return nil, errors.New("Amp list entry has no id or updated timestamp")
		}
		traces[index] = commandTrace{ID: entry.ID, Title: entry.Title, UpdatedAt: entry.Updated}
	}
	return traces, nil
}

func parseOpenCodeList(data []byte) ([]commandTrace, error) {
	var entries []struct {
		ID        string `json:"id"`
		Title     string `json:"title"`
		Updated   int64  `json:"updated"`
		Created   int64  `json:"created"`
		ProjectID string `json:"projectId"`
		Directory string `json:"directory"`
	}
	if err := json.Unmarshal(data, &entries); err != nil {
		return nil, err
	}
	traces := make([]commandTrace, len(entries))
	for index, entry := range entries {
		if entry.ID == "" || entry.Updated <= 0 {
			return nil, errors.New("OpenCode list entry has no id or updated timestamp")
		}
		traces[index] = commandTrace{ID: entry.ID, Title: entry.Title, UpdatedAt: time.UnixMilli(entry.Updated).UTC().Format(time.RFC3339Nano), CWD: entry.Directory}
	}
	return traces, nil
}

func runOutput(parent context.Context, executable string, args []string, limit int64) ([]byte, error) {
	ctx, cancel := context.WithTimeout(parent, commandTimeout)
	defer cancel()
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	command := exec.CommandContext(ctx, executable, args...)
	command.Stdout = &limitedWriter{writer: &stdout, remaining: limit}
	command.Stderr = &limitedWriter{writer: &stderr, remaining: 1 << 20}
	err := command.Run()
	if ctx.Err() != nil {
		return nil, fmt.Errorf("timed out after %s", commandTimeout)
	}
	if err != nil {
		return nil, commandError(err, stderr.String())
	}
	return stdout.Bytes(), nil
}

func runToFile(parent context.Context, executable string, args []string, path string, limit int64) error {
	ctx, cancel := context.WithTimeout(parent, commandTimeout)
	defer cancel()
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	var stderr bytes.Buffer
	command := exec.CommandContext(ctx, executable, args...)
	command.Stdout = &limitedWriter{writer: file, remaining: limit}
	command.Stderr = &limitedWriter{writer: &stderr, remaining: 1 << 20}
	runErr := command.Run()
	closeErr := file.Close()
	if ctx.Err() != nil {
		return fmt.Errorf("timed out after %s", commandTimeout)
	}
	if runErr != nil {
		return commandError(runErr, stderr.String())
	}
	return closeErr
}

type limitedWriter struct {
	writer    io.Writer
	remaining int64
}

func (writer *limitedWriter) Write(data []byte) (int, error) {
	if int64(len(data)) > writer.remaining {
		return 0, errors.New("command output exceeded safety limit")
	}
	written, err := writer.writer.Write(data)
	writer.remaining -= int64(written)
	return written, err
}

func commandError(err error, stderr string) error {
	stderr = strings.TrimSpace(stderr)
	if stderr == "" {
		return err
	}
	if len(stderr) > 500 {
		stderr = stderr[:500] + "…"
	}
	return fmt.Errorf("%w: %s", err, stderr)
}

func inspectCommandExport(harness, path, expectedID string) (commandTrace, error) {
	file, err := os.Open(path)
	if err != nil {
		return commandTrace{}, err
	}
	defer file.Close()
	if harness == "amp" {
		var export struct {
			Version   int        `json:"v"`
			ID        string     `json:"id"`
			Title     string     `json:"title"`
			UpdatedAt string     `json:"updatedAt"`
			Messages  []struct{} `json:"messages"`
			Env       struct {
				Initial struct {
					WorkingDirectory string `json:"workingDirectory"`
					Trees            []struct {
						URI        string `json:"uri"`
						Repository struct {
							URL string `json:"url"`
						} `json:"repository"`
					} `json:"trees"`
				} `json:"initial"`
			} `json:"env"`
		}
		decoder := json.NewDecoder(file)
		if err := decoder.Decode(&export); err != nil {
			return commandTrace{}, err
		}
		if decoder.Decode(&struct{}{}) != io.EOF {
			return commandTrace{}, errors.New("Amp export contains trailing data")
		}
		if export.Version <= 0 || export.ID != expectedID || export.UpdatedAt == "" || export.Messages == nil {
			return commandTrace{}, errors.New("Amp export is missing v, matching id, updatedAt, or messages")
		}
		repository := domain.Repository{}
		for _, tree := range export.Env.Initial.Trees {
			if tree.Repository.URL == "" {
				continue
			}
			repository.Remote = tree.Repository.URL
			if treeURI, err := url.Parse(tree.URI); err == nil && treeURI.Scheme == "file" {
				repository.Root = treeURI.Path
			}
			break
		}
		return commandTrace{ID: export.ID, Title: export.Title, UpdatedAt: export.UpdatedAt, CWD: export.Env.Initial.WorkingDirectory, Repository: repository}, nil
	}
	var export struct {
		Info struct {
			ID        string `json:"id"`
			Title     string `json:"title"`
			ParentID  string `json:"parentID"`
			Directory string `json:"directory"`
			Time      struct {
				Updated int64 `json:"updated"`
			} `json:"time"`
		} `json:"info"`
		Messages []struct{} `json:"messages"`
	}
	decoder := json.NewDecoder(file)
	if err := decoder.Decode(&export); err != nil {
		return commandTrace{}, err
	}
	if decoder.Decode(&struct{}{}) != io.EOF {
		return commandTrace{}, errors.New("OpenCode export contains trailing data")
	}
	if export.Info.ID != expectedID || export.Info.Time.Updated <= 0 || export.Messages == nil {
		return commandTrace{}, errors.New("OpenCode export is missing matching info.id, info.time.updated, or messages")
	}
	return commandTrace{ID: export.Info.ID, Title: export.Info.Title, ParentID: export.Info.ParentID, CWD: export.Info.Directory, UpdatedAt: time.UnixMilli(export.Info.Time.Updated).UTC().Format(time.RFC3339Nano)}, nil
}

package server

import (
	"database/sql"
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"

	"github.com/regutierrez/traicr/internal/domain"
)

func (app *application) transcriptAPI(w http.ResponseWriter, r *http.Request) {
	id, ok := requestID(w, r)
	if !ok {
		return
	}
	limit, ok := pageLimit(w, r)
	if !ok {
		return
	}
	var revision int64
	if value := r.URL.Query().Get("revision"); value != "" {
		var err error
		revision, err = strconv.ParseInt(value, 10, 64)
		if err != nil || revision < 0 {
			writeError(w, 400, "invalid_revision", "revision must be a nonnegative integer")
			return
		}
	}
	page, err := app.store.TranscriptEvents(r.Context(), id, revision, r.URL.Query().Get("cursor"), limit)
	if err != nil {
		app.failure(w, err)
		return
	}
	writeJSON(w, page)
}

func (app *application) resolveTrace(w http.ResponseWriter, r *http.Request) {
	id, err := app.store.TraceID(r.Context(), "amp", r.URL.Query().Get("native_id"))
	if errors.Is(err, sql.ErrNoRows) {
		writeError(w, 404, "trace_not_collected", "This Amp trace has not been collected. Use the original Amp link to inspect it.")
		return
	}
	if err != nil {
		app.failure(w, err)
		return
	}
	http.Redirect(w, r, "/traces/"+strconv.FormatInt(id, 10), http.StatusSeeOther)
}

func (app *application) ampSourceBlock(w http.ResponseWriter, r *http.Request) (any, bool) {
	id, ok := requestID(w, r)
	if !ok {
		return nil, false
	}
	pointer := r.URL.Query().Get("pointer")
	if !strings.HasPrefix(pointer, "/") {
		writeError(w, 400, "invalid_pointer", "source pointer must start with /")
		return nil, false
	}
	sources, err := app.store.RevisionSources(r.Context(), id)
	if err != nil {
		app.failure(w, err)
		return nil, false
	}
	for _, source := range sources {
		if source.Path == "source/export.json" && source.Size > domain.MaxAmpExportBytes {
			writeError(w, 413, "source_too_large", "Source exceeds the 512 MiB Amp limit. Download the native export instead.")
			return nil, false
		}
	}
	file, err := app.store.OpenSource(r.Context(), id, "source/export.json")
	if err != nil {
		app.failure(w, err)
		return nil, false
	}
	defer file.Close()
	var value any
	if err := json.NewDecoder(io.LimitReader(file, domain.MaxAmpExportBytes)).Decode(&value); err != nil {
		writeError(w, 422, "source_unavailable", "Source JSON is invalid or exceeds the 512 MiB Amp limit. Download the native export instead.")
		return nil, false
	}
	for _, key := range strings.Split(pointer[1:], "/") {
		key = strings.ReplaceAll(strings.ReplaceAll(key, "~1", "/"), "~0", "~")
		switch item := value.(type) {
		case map[string]any:
			value = item[key]
		case []any:
			index, err := strconv.Atoi(key)
			if err != nil || index < 0 || index >= len(item) {
				value = nil
			} else {
				value = item[index]
			}
		default:
			value = nil
		}
		if value == nil {
			writeError(w, 404, "block_not_found", "Source block not found")
			return nil, false
		}
	}
	return value, true
}

func (app *application) sourceBlock(w http.ResponseWriter, r *http.Request) {
	value, ok := app.ampSourceBlock(w, r)
	if !ok {
		return
	}
	w.Header().Set("Content-Type", "application/json")
	encoder := json.NewEncoder(w)
	encoder.SetIndent("", "  ")
	_ = encoder.Encode(value)
}

func (app *application) sourceAttachment(w http.ResponseWriter, r *http.Request) {
	value, ok := app.ampSourceBlock(w, r)
	if !ok {
		return
	}
	block, _ := value.(map[string]any)
	source, _ := block["source"].(map[string]any)
	encoded, _ := source["data"].(string)
	if source["type"] != "base64" || encoded == "" {
		writeError(w, 404, "attachment_not_archived", "Attachment bytes are not in this export. External URLs are never fetched automatically.")
		return
	}
	if len(encoded) > base64.StdEncoding.EncodedLen(10<<20) {
		writeError(w, 413, "attachment_too_large", "Image exceeds the 10 MiB preview limit. Download the native export instead.")
		return
	}
	data, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		writeError(w, 422, "invalid_attachment", "Attachment data is not valid base64")
		return
	}
	if len(data) > 10<<20 {
		writeError(w, 413, "attachment_too_large", "Image exceeds the 10 MiB preview limit. Download the native export instead.")
		return
	}
	mediaType := http.DetectContentType(data)
	switch mediaType {
	case "image/png", "image/jpeg", "image/gif", "image/webp":
		w.Header().Set("Content-Type", mediaType)
	default:
		writeError(w, 415, "unsupported_preview", "Only PNG, JPEG, GIF and WebP images can be previewed. Inspect the source block for other attachments.")
		return
	}
	if r.URL.Query().Get("download") == "1" {
		w.Header().Set("Content-Disposition", `attachment; filename="attachment"`)
	}
	_, _ = w.Write(data)
}
package normalize

import (
	"context"
	"encoding/json"
	"fmt"
	"io/fs"

	"github.com/regutierrez/traicr/internal/domain"
)

func normalizeAmp(ctx context.Context, sourceFS fs.FS) (domain.Normalization, error) {
	export, err := readJSON(sourceFS, "source/export.json")
	if err != nil {
		return domain.Normalization{}, err
	}
	messages := objects(export["messages"])
	messagePath := "/messages"
	if len(messages) == 0 {
		thread := object(export["thread"])
		messages = objects(thread["messages"])
		messagePath = "/thread/messages"
		if len(messages) == 0 {
			messages = objects(thread["events"])
			messagePath = "/thread/events"
		}
	}
	var events []domain.Event
	var warnings []domain.Warning
	if id := stringValue(export["id"]); id != "" {
		session := make(map[string]any)
		for _, key := range []string{"id", "title", "created", "updatedAt", "archived", "agentMode", "activatedSkills", "env", "meta"} {
			if value := export[key]; value != nil {
				session[key] = searchableValue("", value)
			}
		}
		metadata, _ := json.Marshal(map[string]any{"session": session, "transcript_order": -1, "transcript_message": "amp-session:" + id})
		events = append(events, domain.Event{Key: "session_info:" + id, Kind: "session_info", Timestamp: timestamp(export["created"]), Text: contentText(session), Metadata: metadata, Sources: source("source/export.json", 0)})
	}
	tools := make(map[string]string)
	for _, message := range messages {
		for _, block := range objects(message["content"]) {
			if firstString(block, "type", "kind") == "tool_use" {
				tools[firstString(block, "toolUseID", "id", "providerToolUseId")] = firstString(block, "name", "tool")
			}
		}
	}
	for messageIndex, message := range messages {
		if err := ctx.Err(); err != nil {
			return domain.Normalization{}, err
		}
		id := numberString(firstValue(message, "id", "messageId", "message_id"))
		role := firstString(message, "role", "sender")
		model := firstString(message, "model", "modelId", "model_id")
		if model == "" {
			model = stringValue(object(message["usage"])["model"])
		}
		parent := numberString(firstValue(message, "parentId", "parent_id"))
		messageTimestamp := timestamp(firstValue(message, "timestamp", "createdAt"))
		if messageTimestamp == "" {
			messageTimestamp = timestamp(object(message["meta"])["sentAt"])
		}
		content := message["content"]
		blocks, isBlocks := content.([]any)
		contentPointer := fmt.Sprintf("%s/%d/content", messagePath, messageIndex)
		if !isBlocks {
			blocks = []any{map[string]any{"type": "text", "text": contentText(content)}}
		}
		if len(blocks) == 0 && message["state"] != nil {
			blocks = []any{map[string]any{"type": "text", "text": ""}}
			isBlocks = false
			contentPointer = fmt.Sprintf("%s/%d", messagePath, messageIndex)
		}
		messageKey := nativeKey("amp-message", id, message)
		parentMessageKey := ""
		if parent != "" {
			parentMessageKey = nativeKey("amp-message", parent, nil)
		}
		for index, raw := range blocks {
			if err := ctx.Err(); err != nil {
				return domain.Normalization{}, err
			}
			block := object(raw)
			kind := firstString(block, "type", "kind")
			pointer := contentPointer
			if isBlocks {
				pointer += fmt.Sprintf("/%d", index)
			}
			metadata := map[string]any{
				"transcript_message": messageKey, "transcript_parent": parentMessageKey, "transcript_order": messageIndex, "transcript_block": index,
				"source_pointer": pointer,
			}
			for key, value := range map[string]any{
				"run": block["run"], "usage": message["usage"], "message_meta": message["meta"], "state": message["state"],
				"hidden": block["hidden"], "block_state": block["blockState"], "complete": block["complete"],
			} {
				if value != nil {
					metadata[key] = searchableValue("", value)
				}
			}
			for key, field := range map[string]string{"start_time": "startTime", "final_time": "finalTime"} {
				if value := timestamp(block[field]); value != "" {
					metadata[key] = value
				}
			}
			event := domain.Event{Role: role, Model: model, Provider: firstString(block, "provider"), Timestamp: messageTimestamp, Sources: source("source/export.json", 0)}
			if event.Timestamp == "" {
				event.Timestamp = timestamp(firstValue(block, "startTime", "finalTime"))
				if event.Timestamp == "" {
					event.Timestamp = timestamp(object(message["usage"])["timestamp"])
				}
			}
			if parent != "" {
				event.ParentKey = nativeKey("message", parent, nil)
			}
			switch kind {
			case "text", "message", "input_text", "output_text":
				event.Kind, event.Text = "message", contentText(block)
			case "thinking", "reasoning":
				event.Kind, event.Text = "reasoning", contentText(block)
			case "summary":
				event.Kind, event.Text = "compaction", contentText(block["summary"])
			case "tool_use", "tool_call", "function_call":
				event.Kind = "tool_call"
				event.Tool = firstString(block, "name", "tool")
				// Amp results refer to its native tool-use ID, not the provider's ID.
				event.CallID = firstString(block, "toolUseID", "id", "providerToolUseId", "callId", "call_id")
				event.Text = readableJSON(firstValue(block, "input", "arguments"))
			case "tool_result", "function_call_output":
				event.Kind = "tool_result"
				event.CallID = firstString(block, "toolUseID", "providerToolUseId", "tool_use_id", "callId", "call_id")
				event.Tool = tools[event.CallID]
				event.Text = ampResultText(block)
				event.Attachments = ampAttachments(block, pointer)
			case "image", "attachment":
				event.Kind = "attachment"
				event.Attachments = ampAttachments(block, pointer)
			default:
				warnings = append(warnings, warning("unsupported_record", "source/export.json: unknown Amp content "+kind))
				event.Kind, event.Text = "unknown", readableJSON(raw)
				metadata["native_type"] = kind
			}
			blockID := stringValue(block["id"])
			if blockID == "" {
				blockID = indexedID(id, index)
			}
			event.Key = nativeKey(event.Kind, blockID, map[string]any{"message": message, "block": block})
			legacyID := stringValue(block["id"])
			if legacyID == "" {
				legacyID = indexedID(firstString(message, "id", "messageId", "message_id"), index)
			}
			legacyKey := nativeKey(event.Kind, legacyID, map[string]any{"message": message, "block": block})
			if legacyKey != event.Key {
				event.LegacyKeys = []string{legacyKey}
			}
			event.Metadata, _ = json.Marshal(metadata)
			events = append(events, event)
		}
	}
	if len(messages) == 0 {
		warnings = append(warnings, warning("unsupported_version", "Amp export has no supported messages"))
	}
	return complete(events, warnings), nil
}

func ampAttachments(value any, pointer string) []domain.Attachment {
	var attachments []domain.Attachment
	switch value := value.(type) {
	case []any:
		for index, item := range value {
			attachments = append(attachments, ampAttachments(item, fmt.Sprintf("%s/%d", pointer, index))...)
		}
	case map[string]any:
		if kind := stringValue(value["type"]); kind == "image" || kind == "attachment" {
			source := object(value["source"])
			attachment := domain.Attachment{
				Name: firstString(value, "name", "filename"), Path: firstString(value, "sourcePath", "path"), URL: firstString(value, "url"),
				MediaType: firstString(value, "mimeType", "media_type"), SourcePointer: pointer,
			}
			if attachment.URL == "" {
				attachment.URL = stringValue(source["url"])
			}
			if attachment.MediaType == "" {
				attachment.MediaType = firstString(source, "media_type", "mimeType")
			}
			attachment.Inline = source["type"] == "base64"
			attachments = append(attachments, attachment)
		}
		for _, key := range []string{"content", "run", "result", "progress", "displayImages"} {
			if nested, ok := value[key]; ok {
				attachments = append(attachments, ampAttachments(nested, pointer+"/"+key)...)
			}
		}
	}
	return attachments
}

func ampResultText(block map[string]any) string {
	if text := contentText(firstValue(block, "content", "output", "result")); text != "" {
		return text
	}
	run := object(block["run"])
	result := firstValue(run, "error", "result")
	if text := contentText(result); text != "" {
		return text
	}
	if message := stringValue(object(result)["message"]); message != "" {
		return message
	}
	return readableJSON(result)
}

func firstString(value map[string]any, keys ...string) string {
	for _, key := range keys {
		if found := stringValue(value[key]); found != "" {
			return found
		}
	}
	return ""
}

func firstValue(value map[string]any, keys ...string) any {
	for _, key := range keys {
		if value[key] != nil {
			return value[key]
		}
	}
	return nil
}
package adapters

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"testing"
)

func TestAmpListPaginatesWithinCLILimitAndDropsRepeatedThreads(t *testing.T) {
	if os.Getenv("TRAICR_TEST_AMP_LIST") == "1" {
		args := os.Args
		limit, _ := strconv.Atoi(args[len(args)-3])
		offset, _ := strconv.Atoi(args[len(args)-1])
		if limit <= 0 || limit > 500 {
			fmt.Fprintln(os.Stderr, "--limit must be an integer <= 500")
			os.Exit(1)
		}
		entries := make([]map[string]string, 0)
		for i := offset; i < offset+limit && i < 501; i++ {
			entries = append(entries, map[string]string{"id": fmt.Sprintf("T-%d", i), "updated": "2026-09-06T00:00:00Z"})
		}
		if offset > 0 {
			// Amp reorders pages between requests, so a later page can repeat earlier threads.
			entries = append(entries, map[string]string{"id": "T-7", "updated": "2026-09-06T00:00:00Z"}, map[string]string{"id": "T-9", "updated": "2026-09-06T00:00:00Z"})
		}
		json.NewEncoder(os.Stdout).Encode(entries)
		os.Exit(0)
	}
	binary, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	command := filepath.Join(dir, "amp")
	if err := os.WriteFile(command, []byte("#!/bin/sh\nexec \"$TRAICR_TEST_BINARY\" -test.run=^TestAmpListPaginatesWithinCLILimitAndDropsRepeatedThreads$ -- \"$@\"\n"), 0o700); err != nil {
		t.Fatal(err)
	}
	t.Setenv("TRAICR_TEST_AMP_LIST", "1")
	t.Setenv("TRAICR_TEST_BINARY", binary)
	traces, warnings := (commandAdapter{name: "amp", executable: command}).listAmp(context.Background())
	if len(warnings) != 1 || warnings[0].Code != "unstable_listing" || len(traces) != 501 {
		t.Fatalf("Amp pagination: %d traces, warnings: %+v", len(traces), warnings)
	}
	for i, trace := range traces {
		if trace.ID != fmt.Sprintf("T-%d", i) {
			t.Fatalf("Amp trace %d: %q", i, trace.ID)
		}
	}
}

func TestAmpCollectUsesExportTimestampWithoutLiveChangeWarning(t *testing.T) {
	if os.Getenv("TRAICR_TEST_AMP_COLLECT") == "1" {
		args := os.Args
		if args[len(args)-2] == "export" {
			fmt.Print(`{"v":1,"id":"T-1","title":"Thread","updatedAt":"2026-09-10T23:07:25.917Z","messages":[],"env":{"initial":{"workingDirectory":"/unavailable/repo","trees":[{"uri":"file:///exported/repo","repository":{"url":"https://github.com/example/project","ref":"main","sha":"fixture-commit","type":"git"}}]}}}`)
		} else {
			fmt.Print(`[{"id":"T-1","title":"Thread","updated":"2026-09-10T15:47:53.910Z","tree":"","messageCount":1}]`)
		}
		os.Exit(0)
	}
	binary, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	command := filepath.Join(t.TempDir(), "amp")
	if err := os.WriteFile(command, []byte("#!/bin/sh\nexec \"$TRAICR_TEST_BINARY\" -test.run=^TestAmpCollectUsesExportTimestampWithoutLiveChangeWarning$ -- \"$@\"\n"), 0o700); err != nil {
		t.Fatal(err)
	}
	t.Setenv("TRAICR_TEST_AMP_COLLECT", "1")
	t.Setenv("TRAICR_TEST_BINARY", binary)
	result, err := (commandAdapter{name: "amp", format: "amp-thread-export", executable: command}).Collect(context.Background(), nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer result.Cleanup()
	if len(result.Warnings) != 0 || len(result.Inputs) != 1 || result.Inputs[0].Descriptor.NativeUpdatedAt != "2026-09-10T23:07:25.917Z" {
		t.Fatalf("Amp collect: %+v, warnings: %+v", result.Inputs, result.Warnings)
	}
	if repository := result.Inputs[0].Descriptor.Repository; repository.Root != "/exported/repo" || repository.Remote != "https://github.com/example/project" {
		t.Fatalf("Amp exported repository: %+v", repository)
	}
}

func TestCommandListSchemasMatchAmpAndOpenCode(t *testing.T) {
	amp, err := parseAmpList([]byte(`[{"id":"T-1","title":"Thread","updated":"2026-09-06T00:00:00Z","tree":"","messageCount":3}]`))
	if err != nil || len(amp) != 1 || amp[0].ID != "T-1" {
		t.Fatalf("Amp list: %+v, %v", amp, err)
	}
	if _, err := parseAmpList([]byte(`{"threads":[{"id":"T-1"}]}`)); err == nil {
		t.Fatal("accepted invented Amp wrapper schema")
	}
	opencode, err := parseOpenCodeList([]byte(`[{"id":"ses_1","title":"Session","updated":1770000000000,"created":1760000000000,"projectId":"p1","directory":"/repo"}]`))
	if err != nil || len(opencode) != 1 || opencode[0].ID != "ses_1" || opencode[0].CWD != "/repo" {
		t.Fatalf("OpenCode list: %+v, %v", opencode, err)
	}
	if _, err := parseOpenCodeList([]byte(`[{"sessionId":"ses_1","updatedAt":"now"}]`)); err == nil {
		t.Fatal("accepted guessed OpenCode aliases")
	}
}

func TestCommandExportSchemasProvideKnownMetadata(t *testing.T) {
	dir := t.TempDir()
	ampPath := filepath.Join(dir, "amp.json")
	if err := os.WriteFile(ampPath, []byte(`{"v":1,"id":"T-1","title":"Thread","updatedAt":"2026-09-06T00:00:00Z","messages":[],"env":{"initial":{"workingDirectory":"/amp-repo"}}}`), 0o600); err != nil {
		t.Fatal(err)
	}
	amp, err := inspectCommandExport("amp", ampPath, "T-1")
	if err != nil || amp.CWD != "/amp-repo" {
		t.Fatalf("Amp export: %+v, %v", amp, err)
	}
	opencodePath := filepath.Join(dir, "opencode.json")
	if err := os.WriteFile(opencodePath, []byte(`{"info":{"id":"ses_1","title":"Session","parentID":"ses_parent","directory":"/repo","time":{"updated":1770000000000}},"messages":[]}`), 0o600); err != nil {
		t.Fatal(err)
	}
	opencode, err := inspectCommandExport("opencode", opencodePath, "ses_1")
	if err != nil || opencode.ParentID != "ses_parent" || opencode.CWD != "/repo" {
		t.Fatalf("OpenCode export: %+v, %v", opencode, err)
	}
}
package collector

import (
	"context"
	"errors"
	"fmt"
	"os"
	"runtime"
	"sort"
	"time"

	"github.com/regutierrez/traicr/internal/archive"
	"github.com/regutierrez/traicr/internal/collector/adapters"
	"github.com/regutierrez/traicr/internal/config"
	"github.com/regutierrez/traicr/internal/domain"
)

type CollectOptions struct {
	Harnesses []string
	Sources   map[string][]string
	OutputDir string
	All       bool
	Version   string
	Progress  CollectProgress
}

// Progress describes one step of a collection. Phases per harness are
// "collecting" (Completed/Total gathered so far; Total is 0 until known),
// "describing" (Completed/Total gathered traces hashed), then "collected"
// (Completed new or changed traces kept out of Total gathered). Once all
// harnesses finish, "archiving" (Total traces) precedes the ZIP write and
// "archived" (Completed traces in Total archives) follows it.
type Progress struct {
	Phase     string
	Harness   string
	Completed int
	Total     int
}

type CollectProgress func(Progress)

type Collection struct {
	Archives []string
	Warnings []domain.Warning
}

func Harnesses() []string {
	all := adapters.All()
	names := make([]string, 0, len(all))
	for _, adapter := range all {
		names = append(names, adapter.Name())
	}
	return names
}

func Sources(ctx context.Context, configured map[string][]string) []adapters.Source {
	all := adapters.All()
	result := make([]adapters.Source, 0, len(all))
	for _, adapter := range all {
		result = append(result, adapter.Discover(ctx, configured[adapter.Name()]))
	}
	return result
}

func Collect(ctx context.Context, cfg config.Collector, options CollectOptions) (Collection, error) {
	if options.OutputDir == "" {
		return Collection{}, errors.New("collection output directory is required")
	}
	selected := map[string]bool{}
	for _, harness := range options.Harnesses {
		selected[harness] = true
	}
	if len(selected) == 0 {
		return Collection{}, errors.New("select at least one harness")
	}
	configured := make(map[string][]string, len(cfg.Sources)+len(options.Sources))
	for harness, roots := range cfg.Sources {
		configured[harness] = append([]string(nil), roots...)
	}
	for harness, roots := range options.Sources {
		configured[harness] = roots
	}
	var inputs []archive.Input
	var warnings []domain.Warning
	var cleanups []func()
	defer func() {
		for _, cleanup := range cleanups {
			cleanup()
		}
	}()
	progress := options.Progress
	if progress == nil {
		progress = func(Progress) {}
	}
	found := map[string]bool{}
	collected := map[string]bool{}
	for _, adapter := range adapters.All() {
		if !selected[adapter.Name()] {
			continue
		}
		found[adapter.Name()] = true
		harness := adapter.Name()
		progress(Progress{Phase: "collecting", Harness: harness})
		result, err := adapter.Collect(ctx, configured[harness], func(completed, total int) {
			progress(Progress{Phase: "collecting", Harness: harness, Completed: completed, Total: total})
		})
		if err != nil {
			return Collection{}, fmt.Errorf("collect %s: %w", adapter.Name(), err)
		}
		if result.Cleanup != nil {
			cleanups = append(cleanups, result.Cleanup)
		}
		warnings = append(warnings, result.Warnings...)
		kept := 0
		for i, input := range result.Inputs {
			progress(Progress{Phase: "describing", Harness: harness, Completed: i + 1, Total: len(result.Inputs)})
			descriptor, err := archive.Describe(ctx, input)
			if err != nil {
				warnings = append(warnings, domain.Warning{Code: "snapshot_failed", Message: adapter.Name() + " " + input.Descriptor.NativeTraceID + ": " + err.Error()})
				continue
			}
			key := StateKey(descriptor.Harness, descriptor.NativeTraceID)
			// Archives with two descriptors for one trace fail validation, so keep the first.
			if collected[key] {
				warnings = append(warnings, domain.Warning{Code: "duplicate_trace", Message: adapter.Name() + " " + descriptor.NativeTraceID + " was collected twice; the repeat was dropped"})
				continue
			}
			collected[key] = true
			acknowledged := cfg.State[key]
			if !options.All && acknowledged.MachineID == cfg.MachineID && acknowledged.Digest == descriptor.RevisionDigest {
				continue
			}
			input.Descriptor = descriptor
			inputs = append(inputs, input)
			kept++
		}
		progress(Progress{Phase: "collected", Harness: harness, Completed: kept, Total: len(result.Inputs)})
	}
	for harness := range selected {
		if !found[harness] {
			return Collection{}, fmt.Errorf("unknown harness %q", harness)
		}
	}
	if len(inputs) == 0 {
		return Collection{Warnings: warnings}, nil
	}
	hostname, err := os.Hostname()
	if err != nil {
		return Collection{}, fmt.Errorf("read hostname: %w", err)
	}
	sort.Slice(inputs, func(i, j int) bool {
		if inputs[i].Descriptor.Harness == inputs[j].Descriptor.Harness {
			return inputs[i].Descriptor.NativeTraceID < inputs[j].Descriptor.NativeTraceID
		}
		return inputs[i].Descriptor.Harness < inputs[j].Descriptor.Harness
	})
	manifest := domain.Manifest{
		FormatVersion:    domain.FormatVersion,
		CollectorVersion: options.Version,
		CreatedAt:        time.Now().UTC().Format(time.RFC3339Nano),
		SourceMachine:    domain.Machine{ID: cfg.MachineID, Hostname: hostname, OS: runtime.GOOS, Arch: runtime.GOARCH},
	}
	progress(Progress{Phase: "archiving", Total: len(inputs)})
	paths, err := archive.Write(ctx, options.OutputDir, manifest, inputs, 0)
	if err != nil {
		return Collection{}, err
	}
	progress(Progress{Phase: "archived", Completed: len(inputs), Total: len(paths)})
	return Collection{Archives: paths, Warnings: warnings}, nil
}

func StateKey(harness, nativeTraceID string) string { return harness + "\x00" + nativeTraceID }
function details(label, body, escape) {
  return `<details class="amp-details"><summary>${escape(label)}</summary>${body}</details>`;
}

function fields(values, escape) {
  return '<dl class="amp-fields">' + Object.entries(values).filter(([,v]) => v !== undefined && v !== null && v !== '').map(([key,value]) => `<dt>${escape(key)}</dt><dd>${escape(typeof value === 'object' ? JSON.stringify(value) : value)}</dd>`).join('') + '</dl>';
}

function jsonDetails(label, value, escape) {
  return value == null ? '' : details(label, `<pre>${escape(JSON.stringify(value,null,2))}</pre>`, escape);
}

function threadLinks(id, label, escape) {
  if (typeof id !== 'string' || !id) return '';
  const match = id.match(/^https:\/\/ampcode\.com\/threads\/([^/?#]+)/);
  if (match) id = match[1];
  return `<div class="amp-related">${escape(label)}: <a href="/traces/resolve?native_id=${encodeURIComponent(id)}">${escape(id)}</a> · <a href="https://ampcode.com/threads/${encodeURIComponent(id)}" target="_blank" rel="noreferrer">Original in Amp ↗</a></div>`;
}

function attachmentHTML(attachment, escape) {
  const name = attachment.name || attachment.path || attachment.media_type || 'Attachment';
  if (attachment.inline && attachment.revisionId && attachment.source_pointer) {
    const url = `/revisions/${encodeURIComponent(attachment.revisionId)}/attachment?pointer=${encodeURIComponent(attachment.source_pointer)}`;
    return details(`Archived image: ${name}`, `<a href="${url}" target="_blank" rel="noreferrer"><img loading="lazy" src="${url}" alt="${escape(name)}" class="message-image"></a><a href="${url}&download=1">Download image</a>`, escape);
  }
  let url;
  try { url = new URL(attachment.url); } catch { url = null; }
  if (url && ['https:','http:'].includes(url.protocol)) {
    return `<div class="amp-attachment">External reference · <a href="${escape(url.href)}" target="_blank" rel="noreferrer">${escape(name)} ↗</a><span> Bytes are not archived; access may require Amp sign-in.</span></div>`;
  }
  return `<div class="amp-attachment">${escape(name)} · Attachment unavailable; inspect the source block.</div>`;
}

function sourceDetails(entry, escape) {
  const links = (entry.sources || []).map(source => {
    const url = source.revisionId && source.pointer ? `/revisions/${encodeURIComponent(source.revisionId)}/block?pointer=${encodeURIComponent(source.pointer)}` : `/events/${encodeURIComponent(source.eventId)}/sources`;
    return `<li><a href="${url}" target="_blank" rel="noreferrer">${escape(source.pointer || source.key || 'Source records')}</a></li>`;
  }).join('');
  const message = entry.message;
  const native = message?.nativeDetails || {};
  const starts = (entry.sources || []).map(s => Date.parse(s.details?.start_time)).filter(Number.isFinite);
  const ends = (entry.sources || []).map(s => Date.parse(s.details?.final_time)).filter(Number.isFinite);
  const duration = starts.length && ends.length ? Math.max(...ends) - Math.min(...starts) : undefined;
  return details('Message details & source', fields({Model:message?.model,Provider:message?.provider,Timestamp:entry.timestamp,'Generation span':duration === undefined ? undefined : `${duration} ms`,State:native.state,'Context tokens':native.usage?.totalInputTokens,'Context limit':native.usage?.maxInputTokens,Usage:native.usage},escape) + `<ul>${links}</ul>`, escape);
}

function renderAmpTool(call, resultEntry, renderers) {
  const {escape,markdown} = renderers;
  const result = resultEntry?.message;
  const run = result?.run;
  const payload = run?.result;
  const status = result?.isError ? 'failed' : payload?.running ? 'running' : run?.status || (result ? 'unknown' : call.details?.complete === false ? 'incomplete arguments' : 'result not collected');
  let body = `<div class="tool-header">${escape(call.name)} <span class="amp-state">Recorded: ${escape(status)}</span></div>`;
  const args = call.arguments || {};
  if (call.name === 'shell_command') body += `<pre class="tool-command">$ ${escape(args.command || '')}</pre>` + fields({'Working directory':args.workdir},escape);
  if (call.name === 'skill') body += fields({Skill:args.name},escape);
  body += jsonDetails('Arguments',args,escape);
  body += fields({'Process ID':payload?.pid},escape);
  if (typeof payload?.exitCode === 'number') body += `<span class="amp-state">Exit code: ${escape(payload.exitCode)}</span>`;
  for (const key of ['thread','threadID','thread_id']) if (typeof args[key] === 'string') body += threadLinks(args[key],call.name === 'send_message_to_thread' ? 'Message to thread' : 'Referenced thread',escape);
  if (result) {
    const text = result.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
    const output = ['shell_command','shell_command_status','shell_command_kill'].includes(call.name) ? `<pre>${escape(text)}</pre>` : `<div class="markdown-content">${markdown(text)}</div>`;
    if (text) body += text.length > 1600 || call.name === 'skill' ? details('Tool output',output,escape) : `<div class="tool-output">${output}</div>`;
    else body += '<div class="amp-state">No text output recorded.</div>';
    if (Array.isArray(payload?.files)) {
      for (const file of payload.files) {
        if (!file || typeof file !== 'object') continue;
        const diff = typeof file.diff === 'string' ? file.diff.split('\n').map(line => `<div class="${line.startsWith('+') ? 'diff-added' : line.startsWith('-') ? 'diff-removed' : 'diff-context'}">${escape(line)}</div>`).join('') : '';
        body += details(`${file.uri || file.path || 'Changed file'} · +${file.additions ?? '?'} −${file.deletions ?? '?'}`, `<pre class="tool-diff">${diff}</pre>`,escape);
      }
    }
    body += result.content.filter(b => b.type === 'attachment').map(a => attachmentHTML(a,escape)).join('');
    if (payload?.threadID) body += threadLinks(payload.threadID,call.name === 'create_thread' ? 'Spawned thread' : 'Referenced thread',escape);
    if (payload && typeof payload === 'object') body += jsonDetails('Structured result',payload,escape);
    body += sourceDetails(resultEntry,escape);
  }
  return `<div class="tool-execution ${result?.isError ? 'error' : status === 'done' ? 'success' : 'pending'}" id="tool-call-${escape(call.id)}">${body}</div>`;
}

export function renderAmpEntry(entry, renderers) {
  const {escape,markdown,copyLink,toolResults,toolCalls} = renderers;
  if (entry.type === 'session_info') return '';
  if (entry.type === 'compaction') return `<section class="amp-summary" id="entry-${escape(entry.id)}">${details('Compaction summary',`<div class="markdown-content">${markdown(entry.summary)}</div>` + sourceDetails(entry,escape),escape)}</section>`;
  if (entry.type === 'custom_message') return `<section class="hook-message" id="entry-${escape(entry.id)}"><strong>Unsupported content · ${escape(entry.sources?.[0]?.details?.native_type || entry.customType)}</strong><pre>${escape(entry.content)}</pre>${sourceDetails(entry,escape)}</section>`;
  const message = entry.message;
  if (!message) return '';
  if (message.role === 'toolResult') {
    if (toolCalls?.has(message.toolCallId)) return '';
    return renderAmpTool({id:message.toolCallId || entry.id,name:message.toolName || 'Unpaired tool result'},entry,renderers);
  }
  const origin = message.nativeDetails?.message_meta;
  const phase = origin?.openAIResponsePhase;
  let body = copyLink(entry.id) + `<div class="message-timestamp">${escape(message.role)}${phase ? ' · ' + escape(phase === 'final_answer' ? 'Final answer' : phase) : ''}${entry.timestamp ? ' · ' + escape(new Date(entry.timestamp).toLocaleString()) : ''}</div>`;
  if (origin?.fromExecutorThreadID) body += threadLinks(origin.fromExecutorThreadID,'From thread',escape);
  if (origin?.fromAutomation) body += '<div class="amp-state">Automation message</div>';
  for (const block of message.content) {
    if (block.type === 'text') body += `<div class="markdown-content">${markdown(block.text)}</div>`;
    else if (block.type === 'hidden') body += details('Hidden context',`<pre>${escape(block.text)}</pre>`,escape);
    else if (block.type === 'thinking') body += `<div class="thinking-block"><div class="thinking-text">${escape(block.thinking || 'Reasoning text not included in export.')}</div><div class="thinking-collapsed">Thinking …</div></div>`;
    else if (block.type === 'attachment') body += attachmentHTML(block,escape);
    else if (block.type === 'toolCall') body += renderAmpTool(block,toolResults.get(block.id),renderers);
  }
  if (message.stopReason && !['stop','toolUse','complete'].includes(message.stopReason)) body += `<div class="error-text">Recorded response state: ${escape(message.stopReason)}</div>`;
  body += sourceDetails(entry,escape);
  return `<section class="${message.role === 'user' ? 'user-message' : 'assistant-message'}" id="entry-${escape(entry.id)}">${body}</section>`;
}

export function renderAmpHeaderDetails(header, entries, {escape}) {
  const messages = entries.filter(e => e.message?.role === 'assistant').map(e => e.message);
  const totals = {};
  for (const [key,label] of [['input','Input tokens'],['output','Output tokens'],['cacheRead','Cache reads'],['cacheWrite','Cache writes']]) {
    const values = messages.map(m => m.usage?.[key]).filter(Number.isFinite);
    totals[label] = values.length ? `${values.reduce((a,b)=>a+b,0)}${values.length < messages.length ? ' (partial)' : ''}` : 'Unknown';
  }
  const native = header.native || {};
  return details('Usage & environment', '<p>Totals cover loaded assistant messages in this view, once per message. Costs are not provided by this export.</p>' + fields(totals,escape) + fields({'Agent mode':native.agentMode,Features:native.meta?.features,Executor:native.meta?.executorType,Archived:native.archived},escape) + jsonDetails('Activated skills',native.activatedSkills,escape) + jsonDetails('Recorded environment',native.env,escape),escape);
}

