package normalize

import (
	"context"
	"fmt"
	"io/fs"
	"sort"

	"github.com/regutierrez/traicr/internal/domain"
)

type piEntry struct {
	record   sourceRecord
	id       string
	parentID string
	model    string
	provider string
	events   []domain.Event
}

type piModelContext struct {
	model    string
	provider string
}

func normalizePi(ctx context.Context, sourceFS fs.FS) (domain.Normalization, error) {
	records, warnings, err := readJSONL(sourceFS, "source/records.jsonl")
	if err != nil {
		return domain.Normalization{}, err
	}
	if len(records) == 0 {
		return complete(nil, warnings), nil
	}
	header := records[0].Value
	if stringValue(header["type"]) != "session" || numberString(header["version"]) != "3" {
		warnings = append(warnings, warning("unsupported_version", "Pi session header is missing or is not version 3"))
		return complete(nil, warnings), nil
	}

	entries, graphWarnings, err := orderPiEntries(ctx, records[1:])
	warnings = append(warnings, graphWarnings...)
	if err != nil {
		return domain.Normalization{}, err
	}
	primaryKeys := make(map[string]string, len(entries))
	for _, entry := range entries {
		entryEvents, entryWarnings, err := decodePiRecord(ctx, entry)
		warnings = append(warnings, entryWarnings...)
		if err != nil {
			return domain.Normalization{}, err
		}
		entry.events = entryEvents
		if len(entryEvents) > 0 {
			primaryKeys[entry.id] = entryEvents[0].Key
		}
	}

	var events []domain.Event
	for _, entry := range entries {
		for _, event := range entry.events {
			event.ParentKey = primaryKeys[entry.parentID]
			events = append(events, event)
		}
	}
	return complete(events, warnings), nil
}

// Pi stores entries as a parent graph, so file order cannot provide either event order or model inheritance.
func orderPiEntries(ctx context.Context, records []sourceRecord) ([]*piEntry, []domain.Warning, error) {
	entries := make(map[string]*piEntry, len(records))
	var warnings []domain.Warning
	for _, record := range records {
		if err := ctx.Err(); err != nil {
			return nil, warnings, err
		}
		id := stringValue(record.Value["id"])
		if id == "" {
			warnings = append(warnings, unknown(record, "entry has no native id"))
			continue
		}
		if previous, exists := entries[id]; exists {
			warnings = append(warnings, warning("duplicate_native_id", fmt.Sprintf("%s line %d duplicates Pi entry %s from line %d", record.Path, record.Line, id, previous.record.Line)))
			continue
		}
		entries[id] = &piEntry{record: record, id: id, parentID: stringValue(record.Value["parentId"])}
	}

	ids := make([]string, 0, len(entries))
	for id := range entries {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	state := make(map[string]uint8, len(entries))
	ordered := make([]*piEntry, 0, len(entries))
	var visitErr error
	var visit func(string)
	visit = func(id string) {
		if visitErr != nil || state[id] == 2 {
			return
		}
		if err := ctx.Err(); err != nil {
			visitErr = err
			return
		}
		if state[id] == 1 {
			warnings = append(warnings, warning("invalid_parent_graph", fmt.Sprintf("Pi entry %s is in a parent cycle", id)))
			return
		}
		state[id] = 1
		entry := entries[id]
		if entry.parentID != "" {
			if entries[entry.parentID] != nil {
				visit(entry.parentID)
			} else {
				warnings = append(warnings, warning("missing_parent", fmt.Sprintf("Pi entry %s references missing parent %s", id, entry.parentID)))
			}
		}
		state[id] = 2
		ordered = append(ordered, entry)
	}
	for _, id := range ids {
		visit(id)
	}
	if visitErr != nil {
		return nil, warnings, visitErr
	}

	contexts := make(map[string]piModelContext, len(entries))
	for _, entry := range ordered {
		model := contexts[entry.parentID]
		if stringValue(entry.record.Value["type"]) == "model_change" {
			model = piModelContext{model: stringValue(entry.record.Value["modelId"]), provider: stringValue(entry.record.Value["provider"])}
		}
		entry.model, entry.provider = model.model, model.provider
		contexts[entry.id] = model
	}
	return ordered, warnings, nil
}

func decodePiRecord(ctx context.Context, entry *piEntry) ([]domain.Event, []domain.Warning, error) {
	value := entry.record.Value
	base := domain.Event{Model: entry.model, Provider: entry.provider, Timestamp: timestamp(value["timestamp"]), Sources: source(entry.record.Path, entry.record.Line)}
	kind := stringValue(value["type"])
	if kind != "message" {
		event := base
		event.Kind = kind
		event.Key = nativeKey(kind, entry.id, value)
		switch kind {
		case "model_change":
			event.Text = event.Provider + "/" + event.Model
		case "compaction", "branch_summary":
			event.Text = stringValue(value["summary"])
			if kind == "branch_summary" {
				event.Branch = stringValue(value["fromId"])
			}
		case "thinking_level_change", "custom_message", "session_info", "label":
			event.Text = contentText(value)
		default:
			return nil, []domain.Warning{unknown(entry.record, "unknown Pi entry type "+kind)}, nil
		}
		return []domain.Event{event}, nil, nil
	}

	message := object(value["message"])
	role := stringValue(message["role"])
	if explicit := stringValue(message["model"]); explicit != "" {
		base.Model = explicit
	}
	if explicit := stringValue(message["provider"]); explicit != "" {
		base.Provider = explicit
	}
	content, structured := message["content"].([]any)
	if !structured {
		event := base
		event.Kind, event.Role, event.Text = "message", role, contentText(message["content"])
		event.CallID, event.Tool = stringValue(message["toolCallId"]), stringValue(message["toolName"])
		if role == "toolResult" || event.CallID != "" {
			event.Kind = "tool_result"
		}
		event.Key = nativeKey(event.Kind, entry.id, value)
		return []domain.Event{event}, nil, nil
	}

	var events []domain.Event
	var warnings []domain.Warning
	for index, raw := range content {
		if err := ctx.Err(); err != nil {
			return nil, warnings, err
		}
		block := object(raw)
		event := base
		event.Role = role
		if role == "toolResult" {
			event.Kind, event.Text = "tool_result", contentText(block)
			event.CallID, event.Tool = stringValue(message["toolCallId"]), stringValue(message["toolName"])
		} else {
			switch stringValue(block["type"]) {
			case "text":
				event.Kind, event.Text = "message", stringValue(block["text"])
			case "thinking":
				event.Kind, event.Text = "reasoning", stringValue(block["thinking"])
			case "toolCall":
				event.Kind, event.Tool, event.CallID = "tool_call", stringValue(block["name"]), stringValue(block["id"])
				event.Text = readableJSON(block["arguments"])
			case "image":
				event.Kind = "attachment"
				event.Attachments = []domain.Attachment{{Name: stringValue(block["name"]), MediaType: firstString(block, "mimeType", "mediaType"), Path: stringValue(block["path"]), URL: stringValue(block["url"])}}
			default:
				warnings = append(warnings, unknown(entry.record, "unknown Pi message content "+stringValue(block["type"])))
				continue
			}
		}
		event.Key = nativeKey(event.Kind, indexedID(entry.id, index), block)
		events = append(events, event)
	}
	return events, warnings, nil
}
package normalize

import (
	"context"
	"io/fs"

	"github.com/regutierrez/traicr/internal/domain"
)

func normalizeClaude(ctx context.Context, sourceFS fs.FS) (domain.Normalization, error) {
	records, warnings, err := readJSONL(sourceFS, "source/records.jsonl")
	if err != nil {
		return domain.Normalization{}, err
	}
	parentKeys := make(map[string]string)
	var events []domain.Event
	for _, record := range records {
		if err := ctx.Err(); err != nil {
			return domain.Normalization{}, err
		}
		value := record.Value
		message := object(value["message"])
		if message == nil {
			warnings = append(warnings, unknown(record, "Claude record has no supported message"))
			continue
		}
		id := stringValue(value["uuid"])
		parent := stringValue(value["parentUuid"])
		role := stringValue(message["role"])
		blocks, ok := message["content"].([]any)
		if !ok {
			blocks = []any{map[string]any{"type": "text", "text": contentText(message["content"])}}
		}
		firstEvent := len(events)
		for index, raw := range blocks {
			if err := ctx.Err(); err != nil {
				return domain.Normalization{}, err
			}
			block := object(raw)
			kind := stringValue(block["type"])
			event := domain.Event{
				Role: role, Model: stringValue(message["model"]), Timestamp: timestamp(value["timestamp"]),
				ParentKey: parent, Sources: source(record.Path, record.Line),
			}
			switch kind {
			case "text":
				event.Kind, event.Text = "message", stringValue(block["text"])
			case "thinking":
				event.Kind, event.Text = "reasoning", stringValue(block["thinking"])
			case "tool_use":
				event.Kind, event.Tool, event.CallID = "tool_call", stringValue(block["name"]), stringValue(block["id"])
				event.Text = readableJSON(block["input"])
			case "tool_result":
				event.Kind, event.CallID, event.Text = "tool_result", stringValue(block["tool_use_id"]), contentText(block["content"])
			case "image", "document":
				event.Kind = "attachment"
				event.Attachments = []domain.Attachment{{Name: stringValue(block["name"]), MediaType: stringValue(object(block["source"])["media_type"]), Path: stringValue(block["path"]), URL: stringValue(block["url"])}}
			default:
				warnings = append(warnings, unknown(record, "unknown Claude content "+kind))
				continue
			}
			event.Key = nativeKey(event.Kind, indexedID(id, index), map[string]any{"message": message, "block": block, "parent": parent})
			events = append(events, event)
		}
		if id != "" && len(events) > firstEvent {
			parentKeys[id] = events[firstEvent].Key
		}
	}
	// Resolve native parent UUIDs only after all records have produced their event keys.
	for index := range events {
		events[index].ParentKey = parentKeys[events[index].ParentKey]
	}
	return complete(events, warnings), nil
}

func normalizeCursorAgent(ctx context.Context, sourceFS fs.FS) (domain.Normalization, error) {
	records, warnings, err := readJSONL(sourceFS, "source/records.jsonl")
	if err != nil {
		return domain.Normalization{}, err
	}
	var events []domain.Event
	for _, record := range records {
		if err := ctx.Err(); err != nil {
			return domain.Normalization{}, err
		}
		value := record.Value
		role := stringValue(value["role"])
		message := object(value["message"])
		if role == "" {
			role = stringValue(message["role"])
		}
		if role != "user" && role != "assistant" && role != "system" {
			warnings = append(warnings, unknown(record, "unsupported Cursor Agent row"))
			continue
		}
		content := value["content"]
		if content == nil {
			content = message["content"]
		}
		id := stringValue(value["id"])
		if id == "" {
			id = stringValue(message["id"])
		}
		parent := stringValue(value["parentMessageId"])
		if parent == "" {
			parent = stringValue(message["parentMessageId"])
		}
		event := domain.Event{Kind: "message", Role: role, Model: stringValue(value["model"]), Timestamp: timestamp(value["timestamp"]), Text: contentText(content), Sources: source(record.Path, record.Line)}
		if parent != "" {
			event.ParentKey = nativeKey("message", parent, nil)
		}
		event.Key = nativeKey(event.Kind, id, map[string]any{"role": role, "content": content, "parent": parent})
		if blocks, ok := content.([]any); ok {
			for _, raw := range blocks {
				if err := ctx.Err(); err != nil {
					return domain.Normalization{}, err
				}
				block := object(raw)
				switch stringValue(block["type"]) {
				case "text":
				case "tool_use":
					tool := event
					tool.Kind, tool.Tool, tool.CallID = "tool_call", stringValue(block["name"]), stringValue(block["id"])
					tool.Text = readableJSON(block["input"])
					tool.Key = nativeKey(tool.Kind, tool.CallID, map[string]any{"record": value, "block": block})
					events = append(events, tool)
				case "tool_result":
					tool := event
					tool.Kind, tool.CallID, tool.Text = "tool_result", stringValue(block["tool_use_id"]), contentText(block["content"])
					tool.Key = nativeKey(tool.Kind, tool.CallID, map[string]any{"record": value, "block": block})
					events = append(events, tool)
				default:
					warnings = append(warnings, unknown(record, "unknown Cursor Agent content "+stringValue(block["type"])))
				}
			}
		}
		if event.Text != "" {
			events = append(events, event)
		}
	}
	return complete(events, warnings), nil
}
// Adapt Traicr's merged, normalized records to Pi's HTML session-entry contract.
// Native source files remain authoritative and are available through the details page.

function nativeMessageKey(event) {
  if (event.metadata?.transcript_message) return event.metadata.transcript_message;
  const key = event.key || String(event.id);
  const native = key.slice(key.indexOf(":") + 1);
  if (native.startsWith("sha256:")) return key;
  return native.replace(/:\d+$/, "");
}

function blockIndex(event) {
  if (Number.isInteger(event.metadata?.transcript_block)) return event.metadata.transcript_block;
  const match = event.key?.match(/:(\d+)$/);
  return match ? Number(match[1]) : event.id;
}

// buildTranscriptSession groups content blocks into turns and retains parent branches.
export function buildTranscriptSession(events, metadata) {
  const native = events.find(event => event.metadata?.session)?.metadata.session;
  const groups = new Map();
  for (const event of events) {
    const key = nativeMessageKey(event);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(event);
  }
  const ordered = [...groups.values()].sort((a, b) => {
    if (Number.isInteger(a[0].metadata?.transcript_order) && Number.isInteger(b[0].metadata?.transcript_order)) {
      return a[0].metadata.transcript_order - b[0].metadata.transcript_order;
    }
    return (a[0].timestamp || "").localeCompare(b[0].timestamp || "") || a.reduce((id,e)=>Math.min(id,e.id),Infinity) - b.reduce((id,e)=>Math.min(id,e.id),Infinity);
  });
  const entries = [];
  const eventEntries = new Map();
  const groupEntries = new Map();
  const groupParents = new Map();
  let previous = null;
  for (const group of ordered) {
    group.sort((a, b) => blockIndex(a) - blockIndex(b) || a.id - b.id);
    const first = group[0];
    const groupKey = nativeMessageKey(first);
    let messageEntry = null;
    let usageAssigned = false;
    const added = [];
    function append(entry) {
      entry.id = String(entry.id);
      entry.parentId = added.at(-1)?.id || null;
      entries.push(entry);
      added.push(entry);
      return entry;
    }
    for (const event of group) {
      const text = String(event.text || "");
      const details = event.metadata || {};
      let entry;
      if (["message", "reasoning", "tool_call", "attachment"].includes(event.kind) && (!event.role || ["user", "assistant"].includes(event.role) || event.kind === "tool_call")) {
        const role = event.role === "user" ? "user" : "assistant";
        if (!messageEntry || messageEntry.message.role !== role) {
          messageEntry = append({id: event.id, type: "message", timestamp: event.timestamp,
            message: {role, content: [], model: event.model, provider: event.provider,
              stopReason: details.state?.type === "cancelled" ? "aborted" : details.state?.type === "error" ? "error" : details.state?.stopReason === "tool_use" ? "toolUse" : details.state?.stopReason === "end_turn" ? "stop" : details.state?.stopReason || details.state?.type || (metadata.harness === "amp" ? undefined : "stop"),
              nativeDetails: details,
              usage: !usageAssigned && details.usage ? {input:details.usage.inputTokens,output:details.usage.outputTokens,cacheRead:details.usage.cacheReadInputTokens,cacheWrite:details.usage.cacheCreationInputTokens} : undefined}});
          if (role === 'assistant' && details.usage) usageAssigned = true;
        }
        entry = messageEntry;
        if (event.kind === "reasoning") entry.message.content.push({type: "thinking", thinking: text});
        else if (event.kind === "tool_call") {
          let args;
          try { args = JSON.parse(text); } catch { args = {raw: text}; }
          if (!args || typeof args !== "object") args = {raw: text};
          entry.message.content.push({type: "toolCall", id: event.call_id || event.key, name: event.tool || "tool", arguments: args, details});
        } else if (event.kind === "attachment") {
          if (metadata.harness === 'amp') entry.message.content.push(...(event.attachments || []).map(a => ({type:"attachment", ...a, revisionId:event.revision_id})));
          else entry.message.content.push({type:"text",text:(event.attachments || []).map(a => `Attachment: ${a.name || a.path || a.url || a.media_type || "See source records"}`).join('\n')});
        } else entry.message.content.push({type: details.hidden ? "hidden" : "text", text});
      } else if (event.kind === "tool_result") {
        const existing = added.find(e => e.message?.role === "toolResult" && e.message.toolCallId === event.call_id);
        entry = existing || append({id: event.id, type: "message", timestamp: event.timestamp,
          message: {role: "toolResult", toolCallId: event.call_id, toolName: event.tool, content: [],
            run:details.run, isError:details.run?.status === "error" || (typeof details.run?.result?.exitCode === "number" && details.run.result.exitCode !== 0)}});
        entry.message.content.push({type: "text", text});
        entry.message.content.push(...(event.attachments || []).map(a => ({type:"attachment", ...a, revisionId:event.revision_id})));
        messageEntry = null;
      } else {
        messageEntry = null;
        if (event.kind === "model_change") entry = append({id:event.id,type:"model_change",timestamp:event.timestamp,modelId:event.model || text,provider:event.provider || ""});
        else if (event.kind === "compaction" || event.kind === "branch_summary") entry = append({id:event.id,type:event.kind,timestamp:event.timestamp,summary:text,tokensBefore:0});
        else if (event.kind === "thinking_level_change") entry = append({id:event.id,type:event.kind,timestamp:event.timestamp,thinkingLevel:text});
        else if (event.kind === "session_info" || event.kind === "label") entry = append({id:event.id,type:event.kind,timestamp:event.timestamp});
        else entry = append({id:event.id,type:"custom_message",timestamp:event.timestamp,customType:event.kind,display:true,content:text});
      }
      entry.sources ||= [];
      entry.sources.push({eventId:event.id, key:event.key, revisionId:event.revision_id, pointer:details.source_pointer, details});
      eventEntries.set(String(event.id), entry.id);
      eventEntries.set(event.key, entry.id);
      for (const alias of event.aliases || []) eventEntries.set(alias, entry.id);
    }
    if (added.length) {
      groupEntries.set(groupKey, {first:added[0],last:added.at(-1)});
      groupParents.set(groupKey, {key:first.parent_key,nativeParent:first.metadata?.transcript_parent,previous});
      previous = added.at(-1).id;
    }
  }
  const entryMap = new Map(entries.map(e => [e.id,e]));
  for (const [key, group] of groupEntries) {
    const parent = groupParents.get(key);
    const nativeParent = parent.nativeParent || (parent.key && nativeMessageKey({key:parent.key}));
    group.first.parentId = groupEntries.get(nativeParent)?.last.id || eventEntries.get(parent.key) || parent.previous;
  }
  // A malformed native graph must not hang Pi's parent walkers.
  const visited = new Set();
  for (const entry of entries) {
    if (visited.has(entry.id)) continue;
    const seen = new Set([entry.id]);
    let node = entry;
    while (node.parentId && entryMap.has(node.parentId) && !visited.has(node.parentId)) {
      if (seen.has(node.parentId)) { node.parentId = null; break; }
      seen.add(node.parentId);
      node = entryMap.get(node.parentId);
    }
    for (const id of seen) visited.add(id);
  }
  return {header: {id:metadata.nativeId, harness:metadata.harness, title:native?.title || metadata.title, timestamp:native?.created || entries.find(e => e.timestamp)?.timestamp, cwd:native?.env?.initial?.workingDirectory || metadata.cwd, native},
    entries, leafId:entries.at(-1)?.id, eventEntries};
}

export async function loadTranscriptSession(metadata) {
  const events = [];
  let cursor = "";
  const cursors = new Set();
  const data = {};
  async function loadMore() {
