func (s *Store) backfillMissingTraceMetadata(ctx context.Context, traceID, revisionID int64, descriptor domain.Descriptor) (bool, error) {
	if descriptor.Title == "" && descriptor.WorkingDirectory == "" {
		return false, nil
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return false, err
	}
	defer tx.Rollback()
	// Never restore stale metadata over a newer revision or overwrite an existing value.
	var searchableMetadata []string
	if descriptor.Title != "" {
		result, err := tx.ExecContext(ctx, `UPDATE traces SET title=? WHERE id=? AND title='' AND updated_at<=?`, descriptor.Title, traceID, canonicalTime(descriptor.NativeUpdatedAt))
		if err != nil {
			return false, err
		}
		changed, err := result.RowsAffected()
		if err != nil {
			return false, err
		}
		if changed != 0 {
			searchableMetadata = append(searchableMetadata, descriptor.Title)
		}
	}
	if descriptor.WorkingDirectory != "" {
		result, err := tx.ExecContext(ctx, `UPDATE traces SET working_directory=? WHERE id=? AND working_directory='' AND updated_at<=?`, descriptor.WorkingDirectory, traceID, canonicalTime(descriptor.NativeUpdatedAt))
		if err != nil {
			return false, err
		}
		changed, err := result.RowsAffected()
		if err != nil {
			return false, err
		}
		if changed != 0 {
			searchableMetadata = append(searchableMetadata, descriptor.WorkingDirectory)
		}
	}
	if len(searchableMetadata) == 0 {
		return false, nil
	}
	if _, err := tx.ExecContext(ctx, `UPDATE observation_revisions SET searchable_text=searchable_text || char(10) || ? WHERE revision_id=?`, strings.Join(searchableMetadata, "\n"), revisionID); err != nil {
		return false, err
	}
	rows, err := tx.QueryContext(ctx, `SELECT x.observation_id,o.event_id,x.searchable_text FROM observation_revisions x JOIN event_observations o ON o.id=x.observation_id WHERE x.revision_id=?`, revisionID)
	if err != nil {
		return false, err
	}
	type metadataSearchText struct {
		observationID, eventID int64
		text                   string
	}
	var texts []metadataSearchText
	for rows.Next() {
		var text metadataSearchText
		if err := rows.Scan(&text.observationID, &text.eventID, &text.text); err != nil {
			rows.Close()
			return false, err
		}
		texts = append(texts, text)
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return false, err
	}
	if _, err := tx.ExecContext(ctx, "DELETE FROM search_chunks WHERE revision_id=?", revisionID); err != nil {
		return false, err
	}
	for _, text := range texts {
		for _, chunk := range searchtext.Chunks(text.text) {
			if _, err := tx.ExecContext(ctx, "INSERT INTO search_chunks(observation_id,revision_id,event_id,content) VALUES(?,?,?,?)", text.observationID, revisionID, text.eventID, chunk); err != nil {
				return false, err
			}
		}
	}
	return true, tx.Commit()
}

func normalizeResult(ctx context.Context, descriptor domain.Descriptor, source fs.FS, normalize func(context.Context, domain.Descriptor, fs.FS) (domain.Normalization, error)) (domain.Normalization, error) {
	normalization, normalizeErr := normalize(ctx, descriptor, source)
	if normalizeErr != nil {
		normalization.Status = "failed"
		normalization.Warnings = append(normalization.Warnings, domain.Warning{Code: "normalizer_error", Message: normalizeErr.Error()})
	}
	if normalization.Status == "" {
		normalization.Status = "normalized"
	}
	if err := validateEvents(normalization.Events); err != nil {
		normalization.Status = "failed"
		normalization.Events = nil
		normalization.Warnings = append(normalization.Warnings, domain.Warning{Code: "invalid_event", Message: err.Error()})
	}
	return normalization, normalizeErr
}

func normalizationSuccessful(status string) bool {
	return status == "normalized"
func (s *Store) eventPosition(ctx context.Context, traceID int64, condition string, value any) (eventCursor, error) {
	var position eventCursor
	err := s.db.QueryRowContext(ctx, "SELECT sort_time,sort_key,id FROM events WHERE trace_id=? AND "+condition, traceID, value).Scan(&position.Time, &position.Key, &position.ID)
	if errors.Is(err, sql.ErrNoRows) {
		aliasCondition := "a.legacy_key=?"
		if condition == "id=?" {
			aliasCondition = "a.legacy_id=?"
		}
		err = s.db.QueryRowContext(ctx, "SELECT e.sort_time,e.sort_key,e.id FROM event_aliases a JOIN events e ON e.trace_id=a.trace_id AND e.event_key=a.event_key WHERE a.trace_id=? AND "+aliasCondition, traceID, value).Scan(&position.Time, &position.Key, &position.ID)
	}
	if err != nil {
		return eventCursor{}, err
	}
	if err := s.db.QueryRowContext(ctx, "SELECT COALESCE(MAX(id),0) FROM events WHERE trace_id=?", traceID).Scan(&position.MaxID); err != nil {
		return eventCursor{}, err
	}
	return position, nil
}

package normalize

import (
	"context"
	"encoding/json"
	"fmt"
	"io/fs"

	"github.com/regutierrez/traicr/internal/amp"
	"github.com/regutierrez/traicr/internal/domain"
)

func normalizeAmp(ctx context.Context, sourceFS fs.FS, files []domain.File) (domain.Normalization, error) {
	export, err := readJSON(sourceFS, "source/export.json")
	if err != nil {
		return domain.Normalization{}, err
	}
	archived := make(map[string]int64, len(files))
	for _, file := range files {
		archived[file.Path] = file.Size
	}
	messages := objects(export["messages"])
	messagePath := "/messages"
	if len(messages) == 0 {
		thread := object(export["thread"])
		messages = objects(thread["messages"])
		messagePath = "/thread/messages"
		if len(messages) == 0 {
			messages = objects(thread["events"])
			messagePath = "/thread/events"
		}
	}
	var events []domain.Event
	var warnings []domain.Warning
	if id := stringValue(export["id"]); id != "" {
		session := make(map[string]any)
		for _, key := range []string{"id", "title", "created", "updatedAt", "archived", "agentMode", "activatedSkills", "env", "meta"} {
			if value := export[key]; value != nil {
				session[key] = searchableValue("", value)
			}
		}
		metadata, _ := json.Marshal(map[string]any{"session": session, "transcript_order": -1, "transcript_message": "amp-session:" + id})
		events = append(events, domain.Event{Key: "session_info:" + id, Kind: "session_info", Timestamp: timestamp(export["created"]), Text: contentText(session), Metadata: metadata, Sources: source("source/export.json", 0)})
	}
	tools := make(map[string]string)
	for _, message := range messages {
		for _, block := range objects(message["content"]) {
			if firstString(block, "type", "kind") == "tool_use" {
				tools[firstString(block, "toolUseID", "id", "providerToolUseId")] = firstString(block, "name", "tool")
			}
		}
	}
	for messageIndex, message := range messages {
		if err := ctx.Err(); err != nil {
			return domain.Normalization{}, err
		}
		id := numberString(firstValue(message, "id", "messageId", "message_id"))
		role := firstString(message, "role", "sender")
		model := firstString(message, "model", "modelId", "model_id")
		if model == "" {
			model = stringValue(object(message["usage"])["model"])
		}
		parent := numberString(firstValue(message, "parentId", "parent_id"))
		messageTimestamp := timestamp(firstValue(message, "timestamp", "createdAt"))
		if messageTimestamp == "" {
			messageTimestamp = timestamp(object(message["meta"])["sentAt"])
		}
		content := message["content"]
		blocks, isBlocks := content.([]any)
		contentPointer := fmt.Sprintf("%s/%d/content", messagePath, messageIndex)
		if !isBlocks {
			blocks = []any{map[string]any{"type": "text", "text": contentText(content)}}
		}
		if len(blocks) == 0 && message["state"] != nil {
			blocks = []any{map[string]any{"type": "text", "text": ""}}
			isBlocks = false
			contentPointer = fmt.Sprintf("%s/%d", messagePath, messageIndex)
		}
		messageKey := nativeKey("amp-message", id, message)
		parentMessageKey := ""
		if parent != "" {
			parentMessageKey = nativeKey("amp-message", parent, nil)
		}
		for index, raw := range blocks {
			if err := ctx.Err(); err != nil {
				return domain.Normalization{}, err
			}
			block := object(raw)
			kind := firstString(block, "type", "kind")
			pointer := contentPointer
			if isBlocks {
				pointer += fmt.Sprintf("/%d", index)
			}
			metadata := map[string]any{
				"transcript_message": messageKey, "transcript_parent": parentMessageKey, "transcript_order": messageIndex, "transcript_block": index,
				"source_pointer": pointer,
			}
			for key, value := range map[string]any{
				"run": block["run"], "usage": message["usage"], "message_meta": message["meta"], "state": message["state"],
				"hidden": block["hidden"], "block_state": block["blockState"], "complete": block["complete"],
			} {
				if value != nil {
					metadata[key] = searchableValue("", value)
				}
			}
			for key, field := range map[string]string{"start_time": "startTime", "final_time": "finalTime"} {
				if value := timestamp(block[field]); value != "" {
					metadata[key] = value
				}
			}
			event := domain.Event{Role: role, Model: model, Provider: firstString(block, "provider"), Timestamp: messageTimestamp, Sources: source("source/export.json", 0)}
			if event.Timestamp == "" {
				event.Timestamp = timestamp(firstValue(block, "startTime", "finalTime"))
				if event.Timestamp == "" {
					event.Timestamp = timestamp(object(message["usage"])["timestamp"])
				}
			}
			if parent != "" {
				event.ParentKey = nativeKey("message", parent, nil)
			}
			switch kind {
			case "text", "message", "input_text", "output_text":
				event.Kind, event.Text = "message", contentText(block)
			case "thinking", "reasoning":
				event.Kind, event.Text = "reasoning", contentText(block)
			case "summary":
				event.Kind, event.Text = "compaction", contentText(block["summary"])
			case "tool_use", "tool_call", "function_call":
				event.Kind = "tool_call"
				event.Tool = firstString(block, "name", "tool")
				// Amp results refer to its native tool-use ID, not the provider's ID.
				event.CallID = firstString(block, "toolUseID", "id", "providerToolUseId", "callId", "call_id")
				event.Text = readableJSON(firstValue(block, "input", "arguments"))
			case "tool_result", "function_call_output":
				event.Kind = "tool_result"
				event.CallID = firstString(block, "toolUseID", "providerToolUseId", "tool_use_id", "callId", "call_id")
				event.Tool = tools[event.CallID]
				event.Text = ampResultText(block)
				event.Attachments = amp.Attachments(block, pointer)
			case "image", "attachment":
				event.Kind = "attachment"
				event.Attachments = amp.Attachments(block, pointer)
			default:
				warnings = append(warnings, warning("unsupported_record", "source/export.json: unknown Amp content "+kind))
				event.Kind, event.Text = "unknown", readableJSON(raw)
				metadata["native_type"] = kind
			}
			for i := range event.Attachments {
				attachment := &event.Attachments[i]
				_, path := amp.AttachmentLocation(attachment.URL)
				if size, ok := archived[path]; ok && path != "" {
					attachment.ArchivedPath, attachment.Size = path, size
				}
			}
			blockID := stringValue(block["id"])
			if blockID == "" {
				blockID = indexedID(id, index)
			}
			event.Key = nativeKey(event.Kind, blockID, map[string]any{"message": message, "block": block})
			legacyID := stringValue(block["id"])
			if legacyID == "" {
				legacyID = indexedID(firstString(message, "id", "messageId", "message_id"), index)
			}
			legacyKey := nativeKey(event.Kind, legacyID, map[string]any{"message": message, "block": block})
			if legacyKey != event.Key {
				event.LegacyKeys = []string{legacyKey}
			}
			event.Metadata, _ = json.Marshal(metadata)
			events = append(events, event)
		}
	}
	if len(messages) == 0 {
		warnings = append(warnings, warning("unsupported_version", "Amp export has no supported messages"))
	}
	return complete(events, warnings), nil
}

func ampResultText(block map[string]any) string {
	if text := contentText(firstValue(block, "content", "output", "result")); text != "" {
		return text
	}
	run := object(block["run"])
	result := firstValue(run, "error", "result")
	if text := contentText(result); text != "" {
		return text
	}
	if message := stringValue(object(result)["message"]); message != "" {
		return message
	}
	return readableJSON(result)
}

func firstString(value map[string]any, keys ...string) string {
	for _, key := range keys {
		if found := stringValue(value[key]); found != "" {
			return found
		}
	}
	return ""
}

func firstValue(value map[string]any, keys ...string) any {
	for _, key := range keys {
		if value[key] != nil {
			return value[key]
		}
	}
	return nil
}
package amp

import (
	"crypto/sha256"
	"fmt"
	"net/url"
	"strings"

	"github.com/regutierrez/traicr/internal/domain"
)

func AttachmentLocation(rawURL string) (downloadURL, archivePath string) {
	u, err := url.Parse(rawURL)
	if err != nil || u.Scheme != "https" || u.Host != "ampcode.com" || u.User != nil || u.RawQuery != "" || u.ForceQuery {
		return "", ""
	}
	name, ok := strings.CutPrefix(u.EscapedPath(), "/user-content/attachments/")
	if !ok || name == "" || name == "." || name == ".." || strings.ContainsAny(name, "/\\%") {
		return "", ""
	}
	u.Fragment, u.RawFragment = "", ""
	downloadURL = u.String()
	return downloadURL, fmt.Sprintf("source/attachments/%x", sha256.Sum256([]byte(downloadURL)))
}

func Attachments(value any, pointer string) []domain.Attachment {
	var attachments []domain.Attachment
	switch value := value.(type) {
	case []any:
		for index, item := range value {
			attachments = append(attachments, Attachments(item, fmt.Sprintf("%s/%d", pointer, index))...)
		}
	case map[string]any:
		if kind := value["type"]; kind == "image" || kind == "attachment" {
			source, _ := value["source"].(map[string]any)
			attachment := domain.Attachment{
				Name: attachmentString(value, "name", "filename"), Path: attachmentString(value, "sourcePath", "path"), URL: attachmentString(value, "url"),
				MediaType: attachmentString(value, "mimeType", "media_type"), SourcePointer: pointer,
			}
			if attachment.URL == "" {
				attachment.URL = attachmentString(source, "url")
			}
			if attachment.URL == "" {
				attachment.URL, _ = AttachmentLocation(attachment.Path)
			}
			if attachment.MediaType == "" {
				attachment.MediaType = attachmentString(source, "media_type", "mimeType")
			}
			attachment.Inline = source["type"] == "base64"
			attachments = append(attachments, attachment)
		}
		for _, key := range []string{"messages", "thread", "events", "content", "run", "result", "progress", "displayImages"} {
			if nested, ok := value[key]; ok {
				attachments = append(attachments, Attachments(nested, pointer+"/"+key)...)
			}
		}
	}
	return attachments
}

func attachmentString(value map[string]any, keys ...string) string {
	for _, key := range keys {
		if found, _ := value[key].(string); found != "" {
			return found
		}
	}
	return ""
}
