		return Collector{}, "", errors.New("collector configuration has no machine_id")
	}
	if cfg.Sources == nil {
		cfg.Sources = map[string][]string{}
	}
	if cfg.State == nil {
		cfg.State = map[string]CollectionRevision{}
	}
