.transcript-brand span { display: inline-block; color: white; background: var(--green); border-radius: 5px; font: bold 24px/32px Georgia, serif; text-align: center; width: 32px; margin-right: 8px; }
#transcript-status { color: var(--muted); font-size: 12px; margin-bottom: 24px; }
#transcript-meta { display: none; }
.header { border: 1px solid var(--line); border-radius: 12px; padding: 28px; }
.session-eyebrow { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; font: 11px/1.6 var(--font-code); letter-spacing: 1px; color: var(--muted); }
.harness-badge { display: inline-block; color: var(--green); background: var(--soft); border: 1px solid var(--line); border-radius: 5px; padding: 4px 10px; font-weight: 600; letter-spacing: 0; }
.header h1 { font: 650 28px/1.3 var(--font-body); color: var(--ink); overflow-wrap: anywhere; }
.help-bar { color: var(--muted); font-size: 12px; }
.header-toggle-btn, .download-json-btn { font: 12px/1.5 var(--font-body); padding: 7px 10px; border-radius: 6px; color: var(--green); }
.header-info { font-size: 13px; gap: 4px; }
.info-value { overflow-wrap: anywhere; min-width: 0; }
.user-message, .assistant-message, .hook-message, .branch-summary { padding: 24px; border: 1px solid var(--line); border-radius: 10px; }
.assistant-message { background: var(--surface); }
.message-timestamp { font: 11px/1.6 var(--font-code); opacity: 1; margin-bottom: 12px; }
.thinking-text { font-size: 13px; }
.tool-execution { border: 1px solid var(--line); border-radius: 8px; }
.tool-command, .tool-output, .tool-diff, .tool-header, pre, code { font-family: var(--font-code); font-size: 12px; line-height: 1.6; }
.tool-command, .tool-header { color: var(--green); }
.tool-output, .tool-diff { color: var(--ink); }
.header-toggle-btn:focus-visible, .download-json-btn:focus-visible, a:focus-visible, .filter-btn:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; }
.amp-details { border: 1px solid var(--line); border-radius: 6px; margin: 12px 0; padding: 10px 14px; font-size: 13px; overflow-wrap: anywhere; }
.amp-details summary { cursor: pointer; color: var(--green); }
.amp-details pre, .tool-execution pre { white-space: pre-wrap; overflow-wrap: anywhere; max-height: 480px; overflow: auto; }
.amp-details a, .amp-related a, .amp-attachment a { color: var(--green); }
.amp-fields { display: grid; grid-template-columns: minmax(100px, 1fr) minmax(0, 3fr); gap: 4px 16px; margin: 12px 0; font-size: 12px; }
.amp-fields dt { color: var(--muted); }
.amp-fields dd { margin: 0; overflow-wrap: anywhere; }
.amp-state { font: 11px/1.6 var(--font-code); color: var(--muted); padding: 4px 8px; }
.amp-attachment, .amp-related { font-size: 12px; overflow-wrap: anywhere; margin: 12px 0; }
.amp-summary { margin: 24px 0; }
.amp-revisions { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-size: 12px; margin: 16px 0; }
.amp-revisions select { max-width: 100%; padding: 7px; font: inherit; border: 1px solid var(--line); border-radius: 6px; background: var(--surface); color: var(--ink); }
.diff-added { color: var(--green); background: var(--soft); }
.diff-removed { color: var(--error); background: #fff1ef; }
.amp-details .message-image { max-width: 100%; max-height: 480px; object-fit: contain; display: block; }
@media (max-width: 900px) {
  #content { padding: 16px 16px 40px; }
  .transcript-navigation { padding-left: 40px; }
  .header { padding: 20px; }
  .header h1 { font-size: 23px; }
  .user-message, .assistant-message, .hook-message, .branch-summary { padding: 18px; }
}

